WITH customer_store_sales AS ( SELECT s.s_store_sk, s.s_store_name, c.c_customer_sk, c.c_customer_id, hd.hd_buy_potential, SUM(ss.ss_net_profit) AS total_net_profit, SUM(ss.ss_quantity) AS total_quantity FROM store_sales ss JOIN customer c ON ss.ss_customer_sk = c.c_customer_sk JOIN store s ON ss.ss_store_sk = s.s_store_sk JOIN household_demographics hd ON ss.ss_hdemo_sk = hd.hd_demo_sk GROUP BY s.s_store_sk, s.s_store_name, c.c_customer_sk, c.c_customer_id, hd.hd_buy_potential ), ranked_customers AS ( SELECT s_store_sk, s_store_name, c_customer_id, hd_buy_potential, total_net_profit, total_quantity, CASE WHEN total_net_profit > 1000 THEN 'High Value' ELSE 'Regular' END AS customer_value_category, RANK() OVER (PARTITION BY s_store_sk ORDER BY total_net_profit DESC) AS profit_rank FROM customer_store_sales ) SELECT s_store_name, c_customer_id, hd_buy_potential, total_net_profit, total_quantity, customer_value_category, profit_rank FROM ranked_customers WHERE profit_rank <= 5 ORDER BY s_store_name, profit_rank
